//! Object selection (doc 03): mesh-picking click → SceneObject root, 2D marquee, glowing AABB brackets.

use std::collections::HashSet;

use bevy::gizmos::config::GizmoConfigStore;
use bevy::gizmos::prelude::*;
use bevy::picking::mesh_picking::{MeshPickingCamera, MeshPickingPlugin, MeshPickingSettings};
use bevy::picking::pointer::PointerButton;
use bevy::picking::prelude::*;
use bevy::prelude::*;
use bevy::window::PrimaryWindow;
use bevy_egui::{EguiContexts, EguiPrimaryContextPass, egui};

use crate::arc_core::*;
use crate::camera::EditorCamera;
use crate::gizmo_3d::{GizmoState, gizmo_system};
use crate::props::SceneObject;

const MARQUEE_THRESHOLD: f32 = 4.0;

/// Soft-deleted object (hidden, kept so undo can bring it back).
#[derive(Component)]
pub struct Deleted;

/// Transform scale at spawn; AABB half extents are expressed at this scale.
#[derive(Component, Clone, Copy)]
pub struct SpawnScale(pub Vec3);

#[derive(Resource, Default)]
pub struct EditorSelection {
    pub primary: Option<Entity>,
    pub selected: HashSet<Entity>,
    pub marquee: Option<(Vec2, Vec2)>,
    press: Option<Vec2>,
    hit_object: bool,
}

impl EditorSelection {
    pub fn clear(&mut self) {
        self.primary = None;
        self.selected.clear();
    }
    pub fn set_one(&mut self, e: Entity) {
        self.selected.clear();
        self.selected.insert(e);
        self.primary = Some(e);
    }
    fn set_all(&mut self, set: HashSet<Entity>) {
        if !self.primary.is_some_and(|p| set.contains(&p)) {
            self.primary = set.iter().copied().min_by_key(|e| e.to_bits());
        }
        self.selected = set;
    }
}

#[derive(Default, Reflect, GizmoConfigGroup)]
pub struct SelectionGizmos;

/// Oriented box of an object: (centre, half extents, rotation). The pivot sits on the object's base.
pub fn object_box(tf: &Transform, so: &SceneObject, base: Option<&SpawnScale>) -> (Vec3, Vec3, Quat) {
    let ratio = base.map_or(Vec3::ONE, |b| tf.scale / b.0.max(Vec3::splat(1e-4)));
    let half = so.aabb_half_extents * ratio.abs();
    (tf.translation + tf.rotation * Vec3::new(0.0, half.y, 0.0), half, tf.rotation)
}

pub struct SelectionPlugin;

impl Plugin for SelectionPlugin {
    fn build(&self, app: &mut App) {
        app.add_plugins(MeshPickingPlugin)
            .insert_resource(MeshPickingSettings { require_markers: true, ..default() })
            .init_resource::<EditorSelection>()
            .init_gizmo_group::<SelectionGizmos>()
            .add_observer(on_click)
            .add_systems(Startup, |mut store: ResMut<GizmoConfigStore>| {
                let (cfg, _) = store.config_mut::<SelectionGizmos>();
                cfg.depth_bias = -0.2;
                cfg.line.width = 3.0;
            })
            .add_systems(Update, (mark_pickable, init_spawn_scale, prune_selection, env_select, selection_input.after(gizmo_system), draw_selection).chain())
            .add_systems(EguiPrimaryContextPass, draw_marquee);
    }
}

fn mark_pickable(
    mut commands: Commands,
    new: Query<Entity, Added<Mesh3d>>,
    parents: Query<&ChildOf>,
    objs: Query<(), With<SceneObject>>,
    cams: Query<Entity, (With<EditorCamera>, Without<MeshPickingCamera>)>,
) {
    for c in &cams {
        commands.entity(c).insert(MeshPickingCamera);
    }
    for e in &new {
        let mut cur = e;
        loop {
            if objs.contains(cur) {
                commands.entity(e).insert(Pickable::default());
                break;
            }
            match parents.get(cur) {
                Ok(p) => cur = p.parent(),
                Err(_) => break,
            }
        }
    }
}

fn init_spawn_scale(mut commands: Commands, q: Query<(Entity, &Transform), (With<SceneObject>, Without<SpawnScale>)>) {
    for (e, tf) in &q {
        commands.entity(e).insert(SpawnScale(tf.scale));
    }
}

fn prune_selection(mut sel: ResMut<EditorSelection>, alive: Query<(), (With<SceneObject>, Without<Deleted>)>) {
    if sel.selected.iter().any(|e| !alive.contains(*e)) {
        sel.selected.retain(|e| alive.contains(*e));
    }
    if sel.primary.is_some_and(|p| !sel.selected.contains(&p)) {
        sel.primary = sel.selected.iter().copied().min_by_key(|e| e.to_bits());
    }
}

/// Dev aid: `ARC_SELECT=<Name>` selects the first object with that name once it exists.
fn env_select(mut sel: ResMut<EditorSelection>, mut done: Local<bool>, q: Query<(Entity, &SceneObject), Without<Deleted>>) {
    if *done {
        return;
    }
    let Ok(name) = std::env::var("ARC_SELECT") else {
        *done = true;
        return;
    };
    if let Some((e, _)) = q.iter().find(|(_, so)| so.name == name) {
        sel.set_one(e);
        *done = true;
    }
}

#[allow(clippy::too_many_arguments)]
fn on_click(
    mut ev: On<PointerClick>,
    keys: Res<ButtonInput<KeyCode>>,
    mut sel: ResMut<EditorSelection>,
    gizmo: Res<GizmoState>,
    objs: Query<(), (With<SceneObject>, Without<Deleted>)>,
    parents: Query<&ChildOf>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut egui: EguiContexts,
) {
    ev.propagate(false);
    let blocked = egui.ctx_mut().map(|c| c.is_pointer_over_egui()).unwrap_or(false);
    let (Some(p0), Some(cur)) = (sel.press, window.cursor_position()) else { return };
    if ev.button != PointerButton::Primary || blocked || gizmo.busy() || p0.distance(cur) > MARQUEE_THRESHOLD {
        return;
    }
    let mut e = ev.original_event_target();
    let root = loop {
        if objs.contains(e) {
            break Some(e);
        }
        match parents.get(e) {
            Ok(p) => e = p.parent(),
            Err(_) => break None,
        }
    };
    let Some(root) = root else { return };
    sel.hit_object = true;
    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
    if shift || ctrl {
        if sel.selected.contains(&root) {
            sel.selected.remove(&root);
            if sel.primary == Some(root) {
                sel.primary = sel.selected.iter().copied().min_by_key(|e| e.to_bits());
            }
        } else {
            sel.selected.insert(root);
            sel.primary = Some(root);
        }
    } else {
        sel.set_one(root);
    }
}

#[allow(clippy::too_many_arguments)]
pub fn selection_input(
    mouse: Res<ButtonInput<MouseButton>>,
    keys: Res<ButtonInput<KeyCode>>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut sel: ResMut<EditorSelection>,
    gizmo: Res<GizmoState>,
    mut egui: EguiContexts,
    cam: Single<(&Camera, &GlobalTransform), With<EditorCamera>>,
    objs: Query<(Entity, &Transform, &SceneObject, Option<&SpawnScale>), Without<Deleted>>,
) {
    let blocked = egui.ctx_mut().map(|c| c.is_pointer_over_egui() || c.egui_wants_pointer_input()).unwrap_or(false);
    let alt = keys.any_pressed([KeyCode::AltLeft, KeyCode::AltRight]);
    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
    let cursor = window.cursor_position();

    if mouse.just_pressed(MouseButton::Left) && !alt && !blocked && !gizmo.busy() {
        sel.press = cursor;
        sel.hit_object = false;
    }
    if mouse.pressed(MouseButton::Left) {
        if let (Some(p0), Some(c)) = (sel.press, cursor) {
            if p0.distance(c) > MARQUEE_THRESHOLD || sel.marquee.is_some() {
                sel.marquee = Some((p0, c));
            }
        }
    }
    if !mouse.just_released(MouseButton::Left) {
        return;
    }
    let marquee = sel.marquee.take();
    if sel.press.take().is_none() {
        return;
    }
    if let Some((a, b)) = marquee {
        let rect = normalize_rect(a, b);
        let (camera, gtf) = *cam;
        let inside: HashSet<Entity> = objs
            .iter()
            .filter(|(_, tf, so, base)| {
                let (c, _, _) = object_box(tf, so, *base);
                camera.world_to_viewport(gtf, c).is_ok_and(|p| rect_contains(rect, p))
            })
            .map(|(e, ..)| e)
            .collect();
        let next = combine_selection(&sel.selected, &inside, shift, ctrl);
        sel.set_all(next);
    } else if !sel.hit_object && !shift && !ctrl {
        sel.clear();
    }
}

fn draw_selection(sel: Res<EditorSelection>, objs: Query<(&Transform, &SceneObject, Option<&SpawnScale>), Without<Deleted>>, mut gizmos: Gizmos<SelectionGizmos>) {
    for e in &sel.selected {
        let Ok((tf, so, base)) = objs.get(*e) else { continue };
        let (c, h, q) = object_box(tf, so, base);
        let (dim, bright) = if sel.primary == Some(*e) {
            (Color::linear_rgb(0.15, 0.7, 1.0), Color::linear_rgb(0.5, 3.0, 4.5))
        } else {
            (Color::linear_rgb(0.1, 0.4, 0.6), Color::linear_rgb(0.3, 1.8, 2.8))
        };
        gizmos.cuboid(Transform { translation: c, rotation: q, scale: h * 2.0 }, dim);
        for s in 0..8u32 {
            let sg = Vec3::new(if s & 1 == 0 { -1.0 } else { 1.0 }, if s & 2 == 0 { -1.0 } else { 1.0 }, if s & 4 == 0 { -1.0 } else { 1.0 });
            let corner = c + q * (sg * h);
            for axis in 0..3 {
                let mut dir = Vec3::ZERO;
                dir[axis] = -sg[axis];
                let len = (h[axis] * 0.5).min(1.6);
                gizmos.line(corner, corner + q * dir * len, bright);
            }
        }
    }
}

fn draw_marquee(mut contexts: EguiContexts, sel: Res<EditorSelection>) {
    let Some((a, b)) = sel.marquee else { return };
    let Ok(ctx) = contexts.ctx_mut() else { return };
    let painter = ctx.layer_painter(egui::LayerId::new(egui::Order::Foreground, egui::Id::new("marquee")));
    let rect = egui::Rect::from_two_pos(egui::pos2(a.x, a.y), egui::pos2(b.x, b.y));
    painter.rect_filled(rect, 0.0, egui::Color32::from_rgba_unmultiplied(80, 170, 255, 40));
    painter.rect_stroke(rect, 0.0, egui::Stroke::new(1.5, egui::Color32::from_rgb(120, 200, 255)), egui::StrokeKind::Inside);
}

//! Industrial 3D gizmo (doc 02/03): Move / Rotate / Scale, surface snapping, duplicate / delete, transactional undo.

use std::f32::consts::TAU;

use bevy::gizmos::config::GizmoConfigStore;
use bevy::gizmos::prelude::*;
use bevy::prelude::*;
use bevy::window::PrimaryWindow;
use bevy_egui::EguiContexts;

use crate::arc_core::*;
use crate::camera::EditorCamera;
use crate::props::SceneObject;
use crate::selection::{Deleted, EditorSelection, prune_selection};
use crate::terrain_render::TerrainGrid;

// geometry in units of the constant-screen-size `handle_size`
const AX_LEN: f32 = 1.2;
const CONE_LEN: f32 = 0.3;
const CONE_R: f32 = 0.09;
const PLANE_A: f32 = 0.35;
const PLANE_B: f32 = 0.7;
const RING_R: f32 = 1.0;
const SCALE_LEN: f32 = 1.1;
const CUBE: f32 = 0.13;
const PICK_PX: f32 = 9.0;
const MOVE_SNAP: f32 = 0.5;
const ROT_SNAP_DEG: f32 = 15.0;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum GizmoMode {
    Select,
    #[default]
    Move,
    Rotate,
    Scale,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum GizmoSpace {
    #[default]
    World,
    Local,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Handle {
    Axis(usize),
    Plane(usize),
    Center,
    Ring(usize),
    ScaleAxis(usize),
    ScaleAll,
}

/// Undo snapshot of one object: transform plus soft-delete flag.
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct ObjState {
    pub entity: Entity,
    pub tf: Transform,
    pub alive: bool,
}

pub type SceneHistory = UndoHistory<Vec<ObjState>>;

struct Drag {
    handle: Handle,
    starts: Vec<(Entity, Transform)>,
    origin: Vec3,
    axes: [Vec3; 3],
    normal: Vec3,
    hs: f32,
    grab_t: f32,
    grab_pt: Vec3,
    grab_ground: Option<Vec3>,
    v_start: Vec3,
    tangent_mode: bool,
    tangent: Vec2,
    acc: f32,
    prev_raw: Option<f32>,
    last_mouse: Vec2,
    mouse0: Vec2,
    p0: Vec2,
    last_delta: Vec3,
    last: Vec<ObjState>,
}

#[derive(Resource)]
pub struct GizmoState {
    pub mode: GizmoMode,
    pub space: GizmoSpace,
    pub snap_ground: bool,
    pub align_normal: bool,
    pub align_strength: f32,
    hover: Option<Handle>,
    drag: Option<Drag>,
}

impl Default for GizmoState {
    fn default() -> Self {
        Self { mode: GizmoMode::Move, space: GizmoSpace::World, snap_ground: false, align_normal: false, align_strength: 1.0, hover: None, drag: None }
    }
}

impl GizmoState {
    /// True while the pointer is on a handle or a drag is running (selection must not react).
    pub fn busy(&self) -> bool {
        self.drag.is_some() || self.hover.is_some()
    }
}

#[derive(Default, Reflect, GizmoConfigGroup)]
pub struct HandleGizmos;

pub struct Gizmo3dPlugin;

impl Plugin for Gizmo3dPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<GizmoState>()
            .init_resource::<SceneHistory>()
            .init_gizmo_group::<HandleGizmos>()
            .add_systems(Startup, setup_gizmo)
            .add_systems(Update, (gizmo_hotkeys, gizmo_system).chain())
            .add_systems(Update, scene_edit_hotkeys.after(gizmo_system).before(prune_selection));
    }
}

fn setup_gizmo(mut store: ResMut<GizmoConfigStore>, mut gz: ResMut<GizmoState>) {
    let (cfg, _) = store.config_mut::<HandleGizmos>();
    cfg.depth_bias = -1.0;
    cfg.line.width = 4.5;
    // dev aid: ARC_GIZMO=select|move|rotate|scale [,local] [,snap] [,align]
    if let Ok(v) = std::env::var("ARC_GIZMO") {
        for t in v.split(',') {
            match t.trim() {
                "select" => gz.mode = GizmoMode::Select,
                "move" => gz.mode = GizmoMode::Move,
                "rotate" => gz.mode = GizmoMode::Rotate,
                "scale" => gz.mode = GizmoMode::Scale,
                "local" => gz.space = GizmoSpace::Local,
                "snap" => gz.snap_ground = true,
                "align" => gz.align_normal = true,
                _ => {}
            }
        }
    }
}

// ───────────────────────────── view helpers ─────────────────────────────

struct View<'a> {
    camera: &'a Camera,
    gtf: &'a GlobalTransform,
    dir: Vec3,
    eye: Vec3,
}

impl View<'_> {
    fn proj(&self, p: Vec3) -> Option<Vec2> {
        self.camera.world_to_viewport(self.gtf, p).ok()
    }
}

struct Frame {
    o: Vec3,
    axes: [Vec3; 3],
    hs: f32,
}

fn plane_uv(i: usize) -> (usize, usize) {
    match i {
        0 => (1, 2),
        1 => (0, 2),
        _ => (0, 1),
    }
}

fn plane_corners(f: &Frame, i: usize) -> [Vec3; 4] {
    let (u, v) = plane_uv(i);
    let p = |a: f32, b: f32| f.o + (f.axes[u] * a + f.axes[v] * b) * f.hs;
    [p(PLANE_A, PLANE_A), p(PLANE_B, PLANE_A), p(PLANE_B, PLANE_B), p(PLANE_A, PLANE_B)]
}

fn ring_points(f: &Frame, i: usize, n: usize) -> Vec<Vec3> {
    let (e1, e2) = (f.axes[(i + 1) % 3], f.axes[(i + 2) % 3]);
    (0..=n)
        .map(|k| {
            let a = k as f32 / n as f32 * TAU;
            f.o + (e1 * a.cos() + e2 * a.sin()) * f.hs * RING_R
        })
        .collect()
}

fn axis_t_screen(view: &View, o: Vec3, a: Vec3, hs: f32, cursor: Vec2) -> Option<f32> {
    let (p0, p1) = (view.proj(o)?, view.proj(o + a * hs)?);
    let d = p1 - p0;
    let l2 = d.length_squared();
    (l2 > 1e-6).then(|| (cursor - p0).dot(d) / l2 * hs)
}

/// Axis parameter of the cursor ray; screen-space fallback inside the dead zone.
fn axis_t(view: &View, o: Vec3, a: Vec3, hs: f32, ray: Ray3d, cursor: Vec2) -> Option<f32> {
    axis_hit_param(o, a, view.dir, ray.origin, *ray.direction).or_else(|| axis_t_screen(view, o, a, hs, cursor))
}

fn pick(view: &View, cursor: Vec2, mode: GizmoMode, f: &Frame) -> Option<Handle> {
    let axis_pick = |len: f32, make: fn(usize) -> Handle| -> Option<Handle> {
        let p0 = view.proj(f.o)?;
        (0..3)
            .filter_map(|i| {
                let p1 = view.proj(f.o + f.axes[i] * len * f.hs)?;
                let d = dist_point_segment(cursor, p0, p1);
                (d < PICK_PX).then_some((d, make(i)))
            })
            .min_by(|a, b| a.0.total_cmp(&b.0))
            .map(|(_, h)| h)
    };
    let centre = view.proj(f.o).is_some_and(|p| p.distance(cursor) < PICK_PX + 2.0);
    match mode {
        GizmoMode::Move => {
            if centre {
                return Some(Handle::Center);
            }
            axis_pick(AX_LEN, Handle::Axis).or_else(|| {
                (0..3).find(|&i| {
                    let c = plane_corners(f, i).map(|p| view.proj(p));
                    matches!(c, [Some(a), Some(b), Some(c), Some(d)] if point_in_quad(cursor, [a, b, c, d]))
                })
                .map(Handle::Plane)
            })
        }
        GizmoMode::Rotate => (0..3)
            .filter_map(|i| {
                let pts: Vec<Vec2> = ring_points(f, i, 64).into_iter().filter_map(|p| view.proj(p)).collect();
                let d = pts.windows(2).map(|w| dist_point_segment(cursor, w[0], w[1])).fold(f32::MAX, f32::min);
                (d < PICK_PX).then_some((d, Handle::Ring(i)))
            })
            .min_by(|a, b| a.0.total_cmp(&b.0))
            .map(|(_, h)| h),
        GizmoMode::Scale => {
            if centre {
                return Some(Handle::ScaleAll);
            }
            axis_pick(SCALE_LEN, Handle::ScaleAxis)
        }
        GizmoMode::Select => None,
    }
}

// ───────────────────────────── hotkeys ─────────────────────────────

fn gizmo_hotkeys(keys: Res<ButtonInput<KeyCode>>, mouse: Res<ButtonInput<MouseButton>>, mut gz: ResMut<GizmoState>, mut egui: EguiContexts) {
    let typing = egui.ctx_mut().map(|c| c.egui_wants_keyboard_input()).unwrap_or(false);
    // RMB held = fly camera (WASD/QE belong to the camera)
    if typing || mouse.pressed(MouseButton::Right) || gz.drag.is_some() || keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]) {
        return;
    }
    for (k, m) in [(KeyCode::KeyQ, GizmoMode::Select), (KeyCode::KeyW, GizmoMode::Move), (KeyCode::KeyE, GizmoMode::Rotate), (KeyCode::KeyR, GizmoMode::Scale)] {
        if keys.just_pressed(k) {
            gz.mode = m;
        }
    }
    if keys.just_pressed(KeyCode::KeyX) {
        gz.space = if gz.space == GizmoSpace::World { GizmoSpace::Local } else { GizmoSpace::World };
    }
}

// ───────────────────────────── drag ─────────────────────────────

fn states_of(list: &[(Entity, Transform)]) -> Vec<ObjState> {
    list.iter().map(|(e, t)| ObjState { entity: *e, tf: *t, alive: true }).collect()
}

fn start_drag(handle: Handle, view: &View, f: &Frame, ray: Ray3d, cursor: Vec2, starts: Vec<(Entity, Transform)>, grid: &HeightfieldGrid) -> Option<Drag> {
    let (ro, rd) = (ray.origin, *ray.direction);
    let mut d = Drag {
        handle,
        starts,
        origin: f.o,
        axes: f.axes,
        normal: Vec3::Y,
        hs: f.hs,
        grab_t: 0.0,
        grab_pt: f.o,
        grab_ground: grid.raycast(ro, rd),
        v_start: Vec3::X,
        tangent_mode: false,
        tangent: Vec2::X,
        acc: 0.0,
        prev_raw: None,
        last_mouse: cursor,
        mouse0: cursor,
        p0: view.proj(f.o)?,
        last_delta: Vec3::ZERO,
        last: Vec::new(),
    };
    match handle {
        Handle::Axis(i) | Handle::ScaleAxis(i) => d.grab_t = axis_t(view, f.o, f.axes[i], f.hs, ray, cursor)?,
        Handle::Plane(_) | Handle::Center => {
            d.normal = if let Handle::Plane(i) = handle { f.axes[i] } else { -view.dir };
            d.grab_pt = plane_drag_point(f.o, d.normal, view.dir, ro, rd)?;
        }
        Handle::Ring(i) => {
            let a = f.axes[i];
            if let Some(p) = plane_drag_point(f.o, a, view.dir, ro, rd) {
                d.v_start = (p - f.o).normalize_or_zero();
            }
            d.tangent_mode = a.dot(view.dir).abs() < 0.08 || d.v_start == Vec3::ZERO;
            if d.tangent_mode {
                let pts = ring_points(f, i, 64);
                let near = (0..pts.len() - 1)
                    .filter_map(|k| Some((dist_point_segment(cursor, view.proj(pts[k])?, view.proj(pts[k + 1])?), k)))
                    .min_by(|a, b| a.0.total_cmp(&b.0))
                    .map(|(_, k)| k)
                    .unwrap_or(0);
                if let (Some(p0), Some(p1)) = (view.proj(pts[near]), view.proj(pts[near + 1])) {
                    d.tangent = (p1 - p0).normalize_or_zero();
                }
            }
        }
        Handle::ScaleAll => {}
    }
    Some(d)
}

fn drag_update(d: &mut Drag, view: &View, ray: Ray3d, cursor: Vec2, ctrl: bool, snap_ground: bool, align: Option<f32>, grid: &HeightfieldGrid) -> Vec<(Entity, Transform)> {
    let (ro, rd) = (ray.origin, *ray.direction);
    let o = d.origin;
    let mut out = Vec::with_capacity(d.starts.len());
    match d.handle {
        Handle::Axis(_) | Handle::Plane(_) | Handle::Center => {
            let mut vertical = false;
            match d.handle {
                Handle::Axis(i) => {
                    let a = d.axes[i];
                    vertical = a.y.abs() > 0.7;
                    let step = ctrl.then_some(MOVE_SNAP);
                    let t = axis_drag_delta(o, a, view.dir, ro, rd, d.grab_t, step).or_else(|| {
                        axis_t_screen(view, o, a, d.hs, cursor).map(|t| {
                            let t = t - d.grab_t;
                            step.map_or(t, |s| (t / s).round() * s)
                        })
                    });
                    if let Some(t) = t {
                        d.last_delta = a * t;
                    }
                }
                _ => {
                    // grazing planes keep the previous delta
                    if let Some(p) = plane_drag_point(o, d.normal, view.dir, ro, rd) {
                        d.last_delta = p - d.grab_pt;
                    }
                    if snap_ground {
                        if let (Some(h), Some(g0)) = (grid.raycast(ro, rd), d.grab_ground) {
                            d.last_delta = Vec3::new(h.x - g0.x, 0.0, h.z - g0.z);
                        }
                    }
                }
            }
            for (e, s) in &d.starts {
                let mut tf = *s;
                tf.translation += d.last_delta;
                if snap_ground && !vertical {
                    let (x, z) = (tf.translation.x, tf.translation.z);
                    tf.translation.y = grid.sample_height(x, z);
                    if let Some(w) = align {
                        tf.rotation = surface_align_rotation(grid.sample_normal(x, z), yaw_of(s.rotation), w);
                    }
                }
                out.push((*e, tf));
            }
        }
        Handle::Ring(i) => {
            let a = d.axes[i];
            if d.tangent_mode {
                d.acc += (cursor - d.last_mouse).dot(d.tangent) * 0.5_f32.to_radians();
            } else if let Some(raw) = disc_rotation_angle(o, a, view.dir, ro, rd, d.v_start, None) {
                if let Some(pr) = d.prev_raw {
                    d.acc += wrap_angle(raw - pr);
                }
                d.prev_raw = Some(raw);
            }
            let angle = if ctrl {
                let st = ROT_SNAP_DEG.to_radians();
                (d.acc / st).round() * st
            } else {
                d.acc
            };
            let q = Quat::from_axis_angle(a, angle);
            for (e, s) in &d.starts {
                let tf = Transform { translation: o + q * (s.translation - o), rotation: (q * s.rotation).normalize(), scale: s.scale };
                out.push((*e, tf));
            }
        }
        Handle::ScaleAxis(_) | Handle::ScaleAll => {
            let (axis, f) = match d.handle {
                Handle::ScaleAxis(i) => (Some(i), axis_t(view, o, d.axes[i], d.hs, ray, cursor).map_or(1.0, |t| scale_factor(t, d.grab_t))),
                _ => (None, scale_factor(cursor.distance(d.p0), d.mouse0.distance(d.p0))),
            };
            let mut k = Vec3::ONE;
            match axis {
                Some(i) => k[i] = f,
                None => k = Vec3::splat(f),
            }
            for (e, s) in &d.starts {
                out.push((*e, Transform { scale: s.scale * k, ..*s }));
            }
        }
    }
    d.last_mouse = cursor;
    out
}

// ───────────────────────────── drawing ─────────────────────────────

fn axis_color(i: usize, lit: bool) -> Color {
    if lit {
        return Color::linear_rgb(3.0, 2.6, 0.3);
    }
    match i {
        0 => Color::linear_rgb(2.6, 0.25, 0.25),
        1 => Color::linear_rgb(0.4, 2.4, 0.4),
        _ => Color::linear_rgb(0.4, 0.9, 2.8),
    }
}

fn draw_gizmo(g: &mut Gizmos<HandleGizmos>, mode: GizmoMode, f: &Frame, hover: Option<Handle>, drag: Option<&Drag>) {
    let active = drag.map(|d| d.handle);
    let lit = |h: Handle| hover == Some(h) || active == Some(h);
    let o = f.o;
    let hs = f.hs;
    let white = |l: bool| if l { Color::linear_rgb(3.0, 2.6, 0.3) } else { Color::linear_rgb(2.5, 2.5, 2.5) };
    match mode {
        GizmoMode::Move => {
            for i in 0..3 {
                let a = f.axes[i];
                let c = axis_color(i, lit(Handle::Axis(i)));
                let base = o + a * (AX_LEN - CONE_LEN) * hs;
                let tip = o + a * AX_LEN * hs;
                g.line(o + a * 0.14 * hs, base, c);
                let (u, v) = (f.axes[(i + 1) % 3], f.axes[(i + 2) % 3]);
                let rim: Vec<Vec3> = (0..=16).map(|k| base + (u * (k as f32 / 16.0 * TAU).cos() + v * (k as f32 / 16.0 * TAU).sin()) * CONE_R * hs).collect();
                for p in rim.iter().step_by(2) {
                    g.line(tip, *p, c);
                }
                g.linestrip(rim, c);
                // plane quad: outline + hatch fill
                let q = plane_corners(f, i);
                let pc = axis_color(i, lit(Handle::Plane(i)));
                g.linestrip([q[0], q[1], q[2], q[3], q[0]], pc);
                for t in [0.2_f32, 0.4, 0.6, 0.8] {
                    g.line(q[0].lerp(q[1], t), q[3].lerp(q[2], t), pc);
                }
            }
            g.sphere(o, 0.07 * hs, white(lit(Handle::Center)));
        }
        GizmoMode::Rotate => {
            for i in 0..3 {
                let h = Handle::Ring(i);
                g.linestrip(ring_points(f, i, 64), axis_color(i, lit(h)));
                if let Some(d) = drag.filter(|d| d.handle == h && !d.tangent_mode) {
                    let a = f.axes[i];
                    let w = a.cross(d.v_start);
                    let n = 24;
                    let pts: Vec<Vec3> = (0..=n).map(|k| { let t = d.acc * k as f32 / n as f32; o + (d.v_start * t.cos() + w * t.sin()) * hs * RING_R }).collect();
                    for p in pts.iter().step_by(2) {
                        g.line(o, *p, Color::linear_rgb(3.0, 2.6, 0.3));
                    }
                }
            }
            g.sphere(o, 0.05 * hs, white(false));
        }
        GizmoMode::Scale => {
            let rot = Quat::from_mat3(&Mat3::from_cols(f.axes[0], f.axes[1], f.axes[2]));
            for i in 0..3 {
                let c = axis_color(i, lit(Handle::ScaleAxis(i)));
                let end = o + f.axes[i] * SCALE_LEN * hs;
                g.line(o, end, c);
                g.cuboid(Transform { translation: end, rotation: rot, scale: Vec3::splat(CUBE * 2.0 * hs) }, c);
            }
            g.cuboid(Transform { translation: o, rotation: rot, scale: Vec3::splat(CUBE * 1.6 * hs) }, white(lit(Handle::ScaleAll)));
        }
        GizmoMode::Select => {}
    }
}

// ───────────────────────────── main system ─────────────────────────────

#[allow(clippy::too_many_arguments)]
pub fn gizmo_system(
    mouse: Res<ButtonInput<MouseButton>>,
    keys: Res<ButtonInput<KeyCode>>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut egui: EguiContexts,
    cam: Single<(&Camera, &GlobalTransform, &Projection, &EditorCamera)>,
    terrain: Res<TerrainGrid>,
    sel: Res<EditorSelection>,
    mut gz: ResMut<GizmoState>,
    mut hist: ResMut<SceneHistory>,
    mut objs: Query<(&mut Transform, &SceneObject), Without<Deleted>>,
    mut gizmos: Gizmos<HandleGizmos>,
) {
    let blocked = egui.ctx_mut().map(|c| c.is_pointer_over_egui() || c.egui_wants_pointer_input()).unwrap_or(false);
    let (camera, gtf, proj, ecam) = *cam;
    let fov = if let Projection::Perspective(p) = proj { p.fov } else { 1.0 };
    let view = View { camera, gtf, dir: *gtf.forward(), eye: gtf.translation() };
    let alt = keys.any_pressed([KeyCode::AltLeft, KeyCode::AltRight]);
    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
    let grid = &terrain.0;

    let primary = sel.primary.filter(|e| objs.contains(*e));
    let Some(primary) = primary.filter(|_| gz.mode != GizmoMode::Select) else {
        if let Some(d) = gz.drag.take() {
            for (e, t) in &d.starts {
                if let Ok((mut tf, _)) = objs.get_mut(*e) {
                    *tf = *t;
                }
            }
            hist.cancel();
        }
        gz.hover = None;
        return;
    };
    let (origin, prot) = objs.get(primary).map(|(t, _)| (t.translation, t.rotation)).unwrap_or_default();
    let space = if gz.mode == GizmoMode::Scale { GizmoSpace::Local } else { gz.space };
    let axes = match space {
        GizmoSpace::World => [Vec3::X, Vec3::Y, Vec3::Z],
        GizmoSpace::Local => [prot * Vec3::X, prot * Vec3::Y, prot * Vec3::Z],
    };
    let hs = calc_handle_size(view.eye, origin, view.dir, fov).max(1e-3);
    let frame = Frame { o: origin, axes, hs };
    let cursor = window.cursor_position();
    let ray = cursor.and_then(|c| camera.viewport_to_world(gtf, c).ok());
    let cam_busy = ecam.mode.is_some() || alt;

    if gz.drag.is_none() {
        gz.hover = match (cursor, blocked || cam_busy) {
            (Some(c), false) => pick(&view, c, gz.mode, &frame),
            _ => None,
        };
        if mouse.just_pressed(MouseButton::Left) {
            if let (Some(h), Some(c), Some(r)) = (gz.hover, cursor, ray) {
                let starts: Vec<(Entity, Transform)> = sel.selected.iter().filter_map(|e| objs.get(*e).ok().map(|(t, _)| (*e, *t))).collect();
                if let Some(d) = start_drag(h, &view, &frame, r, c, starts, grid) {
                    let label = match gz.mode {
                        GizmoMode::Rotate => "Rotate",
                        GizmoMode::Scale => "Scale",
                        _ => "Move",
                    };
                    hist.begin(label, states_of(&d.starts));
                    gz.drag = Some(d);
                }
            }
        }
    }

    if let Some(mut d) = gz.drag.take() {
        if keys.just_pressed(KeyCode::Escape) {
            for (e, t) in &d.starts {
                if let Ok((mut tf, _)) = objs.get_mut(*e) {
                    *tf = *t;
                }
            }
            hist.cancel();
        } else {
            if let (Some(c), Some(r)) = (cursor, ray) {
                let align = gz.align_normal.then_some(gz.align_strength);
                let res = drag_update(&mut d, &view, r, c, ctrl, shift || gz.snap_ground, align, grid);
                for (e, t) in &res {
                    if let Ok((mut tf, _)) = objs.get_mut(*e) {
                        *tf = *t;
                    }
                }
                d.last = states_of(&res);
                hist.update_preview(d.last.clone());
            }
            if mouse.pressed(MouseButton::Left) {
                gz.drag = Some(d);
            } else {
                let fin = if d.last.is_empty() { states_of(&d.starts) } else { d.last.clone() };
                hist.commit(fin);
            }
        }
    }

    let hover = gz.hover;
    let mode = gz.mode;
    draw_gizmo(&mut gizmos, mode, &frame, hover, gz.drag.as_ref());
}

// ───────────────────────────── duplicate / delete / undo ─────────────────────────────

fn apply_states(states: &[ObjState], q: &mut Query<(&mut Transform, &mut Visibility)>, commands: &mut Commands) {
    for s in states {
        let Ok((mut tf, mut vis)) = q.get_mut(s.entity) else { continue };
        *tf = s.tf;
        *vis = if s.alive { Visibility::Inherited } else { Visibility::Hidden };
        if s.alive {
            commands.entity(s.entity).try_remove::<Deleted>();
        } else {
            commands.entity(s.entity).try_insert(Deleted);
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn scene_edit_hotkeys(
    keys: Res<ButtonInput<KeyCode>>,
    mut egui: EguiContexts,
    mut commands: Commands,
    mut sel: ResMut<EditorSelection>,
    mut hist: ResMut<SceneHistory>,
    gz: Res<GizmoState>,
    terrain: Res<TerrainGrid>,
    mut q: Query<(&mut Transform, &mut Visibility)>,
    all: Query<&SceneObject>,
) {
    if egui.ctx_mut().map(|c| c.egui_wants_keyboard_input()).unwrap_or(false) || gz.drag.is_some() {
        return;
    }
    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);

    if ctrl && keys.just_pressed(KeyCode::KeyZ) && !shift {
        if let Some(s) = hist.undo() {
            apply_states(&s, &mut q, &mut commands);
        }
    } else if ctrl && (keys.just_pressed(KeyCode::KeyY) || (shift && keys.just_pressed(KeyCode::KeyZ))) {
        if let Some(s) = hist.redo() {
            apply_states(&s, &mut q, &mut commands);
        }
    }

    if ctrl && keys.just_pressed(KeyCode::KeyD) && !sel.selected.is_empty() {
        let grid = &terrain.0;
        let mut next_id = all.iter().map(|o| o.id).max().unwrap_or(0);
        let (mut before, mut after, mut fresh) = (Vec::new(), Vec::new(), Vec::new());
        for src in sel.selected.iter().copied() {
            let (Ok((tf, _)), Ok(so)) = (q.get(src), all.get(src)) else { continue };
            let off = Vec3::new((so.aabb_half_extents.x * 2.0 + 1.0).clamp(1.5, 6.0), 0.0, 0.0);
            let mut ntf = *tf;
            let lift = tf.translation.y - grid.sample_height(tf.translation.x, tf.translation.z);
            ntf.translation += off;
            ntf.translation.y = grid.sample_height(ntf.translation.x, ntf.translation.z) + lift;
            next_id += 1;
            let mut dup = so.clone();
            dup.id = next_id;
            let id = commands
                .entity(src)
                .clone_and_spawn_with_opt_out(|b| {
                    b.linked_cloning(true);
                })
                .insert((ntf, dup))
                .id();
            before.push(ObjState { entity: id, tf: ntf, alive: false });
            after.push(ObjState { entity: id, tf: ntf, alive: true });
            fresh.push(id);
        }
        if let Some(first) = fresh.first().copied() {
            hist.record("Duplicate", before, after);
            sel.selected = fresh.into_iter().collect();
            sel.primary = Some(first);
        }
    }

    if keys.just_pressed(KeyCode::Delete) && !sel.selected.is_empty() {
        let (mut before, mut after) = (Vec::new(), Vec::new());
        for e in sel.selected.iter().copied() {
            let Ok((tf, _)) = q.get(e) else { continue };
            before.push(ObjState { entity: e, tf: *tf, alive: true });
            after.push(ObjState { entity: e, tf: *tf, alive: false });
        }
        if hist.record("Delete", before, after.clone()) {
            apply_states(&after, &mut q, &mut commands);
            sel.clear();
        }
    }
}

